using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEditor.Rendering;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
namespace Deepsea.Editor {
public static class StyleTrialBuild {
 const string Root="Assets/Deepsea/ThirdParty/StyleTrial/";const string Out="Assets/Deepsea/Resources/StyleTrial/";
 public static void Build(){ProjectSetup.EnsureProject();Directory.CreateDirectory(Out);AssetDatabase.Refresh();
  var modelImporter=AssetImporter.GetAtPath(Root+"VertexBlend/FBX/Cliff.fbx") as ModelImporter;if(modelImporter!=null&&!modelImporter.isReadable){modelImporter.isReadable=true;modelImporter.SaveAndReimport();}var meshes=AssetDatabase.LoadAllAssetsAtPath(Root+"VertexBlend/FBX/Cliff.fbx").OfType<Mesh>().ToArray();if(meshes.Length==0)throw new Exception("No imported cliff mesh");var mesh=UnityEngine.Object.Instantiate(meshes.OrderByDescending(m=>m.vertexCount).First());Put(mesh,Out+"CliffMesh.asset");
  var mat=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<Material>(Root+"VertexBlend/Materials/Cliff.mat"));mat.name="Trial Cliff Material";CoolRock(mat);Put(mat,Out+"CliffMaterial.mat");
  var tree=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"StylizedTrees/Prefabs/Trees/Tree_01.prefab");if(tree==null)throw new Exception("No tree prefab");var instance=UnityEngine.Object.Instantiate(tree);PrefabUtility.SaveAsPrefabAsset(instance,Out+"Tree.prefab");UnityEngine.Object.DestroyImmediate(instance);
  string fixture="Tools/StyleCandidates/ImporterFixture/VertexDemo_1K";Directory.CreateDirectory(fixture);File.Copy(Root+"VertexBlend/Textures/SandstoneCliff_albedo.png",fixture+"/VertexDemo_1K_Color.png",true);File.Copy(Root+"VertexBlend/Textures/SandstoneCliff_normal.png",fixture+"/VertexDemo_1K_NormalGL.png",true);File.WriteAllText(fixture+"/VertexDemo.mtlx","<!-- GitHub demo maps; not ambientCG content. -->");
  string importOut="Assets/Deepsea/StyleTrialImported";if(AssetDatabase.IsValidFolder(importOut))AssetDatabase.DeleteAsset(importOut);
  var cfg=new z3lx.ACGImporter.Editor.ImporterConfig{InputPath=fixture,OutputPath=importOut,Shader=Shader.Find("Universal Render Pipeline/Lit"),ShaderProperties=new List<z3lx.ACGImporter.Editor.ShaderProperty>{new z3lx.ACGImporter.Editor.ShaderProperty("_BaseMap",z3lx.ACGImporter.Editor.MapType.Color),new z3lx.ACGImporter.Editor.ShaderProperty("_BumpMap",z3lx.ACGImporter.Editor.MapType.Normal),new z3lx.ACGImporter.Editor.ShaderProperty("_Smoothness",.25f)}};z3lx.ACGImporter.Editor.Importer.AutoImport(cfg);AssetDatabase.Refresh();var acg=AssetDatabase.LoadAssetAtPath<Material>(importOut+"/VertexDemo_Material.mat");if(acg==null||acg.GetTexture("_BaseMap")==null||acg.GetTexture("_BumpMap")==null)throw new Exception("ACG importer material failed");var acgClone=UnityEngine.Object.Instantiate(acg);acgClone.EnableKeyword("_NORMALMAP");Put(acgClone,Out+"ACGMaterial.mat");
  var original=GraphicsSettings.renderPipelineAsset as UniversalRenderPipelineAsset;if(original==null)throw new Exception("No URP");var pipeline=UnityEngine.Object.Instantiate(original);var data=new SerializedObject(original).FindProperty("m_RendererDataList").GetArrayElementAtIndex(0).objectReferenceValue as UniversalRendererData;var renderer=UnityEngine.Object.Instantiate(data);Put(renderer,Out+"TrialRenderer.asset");
  var feature=ScriptableObject.CreateInstance<VolumetricFogRendererFeature>();feature.name="Trial Volumetric Fog";AssetDatabase.AddObjectToAsset(feature,renderer);renderer.rendererFeatures.Add(feature);feature.SetActive(true);feature.Create();EditorUtility.SetDirty(renderer);
  Put(pipeline,Out+"TrialPipeline.asset");var so=new SerializedObject(pipeline);so.FindProperty("m_RendererDataList").GetArrayElementAtIndex(0).objectReferenceValue=renderer;so.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(pipeline);AssetDatabase.SaveAssets();
  foreach(var shader in new[]{mat.shader,acg.shader}.Concat(AssetDatabase.FindAssets("t:Shader",new[]{Root+"StylizedTrees"}).Select(g=>AssetDatabase.LoadAssetAtPath<Shader>(AssetDatabase.GUIDToAssetPath(g))))){if(shader==null)continue;foreach(var e in ShaderUtil.GetShaderMessages(shader))if(e.severity==ShaderCompilerMessageSeverity.Error)throw new Exception(shader.name+": "+e.message);}
  Directory.CreateDirectory("Verification/style-trial-v1");File.WriteAllText("Verification/style-trial-v1/import-audit.json","{\"acgImporter\":true,\"cliffMeshes\":"+meshes.Length+",\"cliffVertices\":"+mesh.vertexCount+",\"treePrefab\":true,\"volumetricRenderer\":true}");
  string output="Builds/StyleTrialV1";Directory.CreateDirectory(output);var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{ProjectSetup.MainScene},locationPathName=output+"/GuichaoBay.exe",target=BuildTarget.StandaloneWindows64,options=BuildOptions.None});if(report.summary.result!=UnityEditor.Build.Reporting.BuildResult.Succeeded)throw new Exception("Style trial build failed");
  foreach(var item in new[]{"VertexBlend","StylizedTrees","ACGImporter","VolumetricLight"}){string source="Tools/StyleCandidates/"+item;string target=output+"/ThirdParty/StyleTrial/"+item;Directory.CreateDirectory(target);foreach(var f in Directory.GetFiles(source))if(Path.GetFileName(f).StartsWith("LICENSE",StringComparison.OrdinalIgnoreCase)||Path.GetExtension(f)==".md")File.Copy(f,target+"/"+Path.GetFileName(f),true);}Debug.Log("STYLE_TRIAL_BUILD_OK");
 }
 static void CoolRock(Material mat){string prop="_Albedo_R";var source=mat.GetTexture(prop) as Texture2D;if(source==null)return;var image=new Texture2D(2,2);image.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(source)));var pixels=image.GetPixels();for(int i=0;i<pixels.Length;i++){float l=pixels[i].grayscale;pixels[i]=new Color(l*.78f,l*.88f,l*.94f,pixels[i].a);}image.SetPixels(pixels);image.Apply();string path=Out+"CoolRock.png";File.WriteAllBytes(path,image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);AssetDatabase.ImportAsset(path);mat.SetTexture(prop,AssetDatabase.LoadAssetAtPath<Texture2D>(path));}
 static void Put(UnityEngine.Object obj,string path){if(AssetDatabase.LoadMainAssetAtPath(path)!=null)AssetDatabase.DeleteAsset(path);AssetDatabase.CreateAsset(obj,path);}
}
}
